import{_ as a,o as s,c as r,a2 as o}from"./chunks/framework.DncwoWA8.js";const t="/projects/ai-skills/diagrams/research-a-decision.svg",f=JSON.parse('{"title":"Research before choosing an approach","description":"","frontmatter":{"title":"Research before choosing an approach"},"headers":[],"relativePath":"workflows/research-a-decision.md","filePath":"workflows/research-a-decision.md"}'),i={name:"workflows/research-a-decision.md"};function n(l,e,c,h,d,p){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="research-before-choosing-an-approach" tabindex="-1">Research before choosing an approach <a class="header-anchor" href="#research-before-choosing-an-approach" aria-label="Permalink to &quot;Research before choosing an approach&quot;">​</a></h1><p>This is a focused procedure. For its place in a larger workflow, see <a href="/projects/ai-skills/workflows/plan-a-project.html">Plan a project or feature</a>.</p><p>Missing facts could change a technical or product decision.</p><p><strong>Finish with:</strong> An evidence-backed comparison with explicit unknowns and a decision boundary.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+t+'" alt="Research before choosing an approach: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/research-a-decision.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/research-a-decision.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/research-a-decision.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. This selection includes the catalogued instruction requirements <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a>. Resolve them before use.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Frame the decision.</strong> <a href="/projects/ai-skills/skills/research.html"><code>research</code></a> provides the guidance for this step.</li><li><strong>Resolve unclear constraints.</strong> <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> provides the guidance for this step.</li><li><strong>Gather and compare evidence.</strong> <a href="/projects/ai-skills/skills/research.html"><code>research</code></a> provides the guidance for this step.</li><li><strong>Report findings and limits.</strong> <a href="/projects/ai-skills/skills/research.html"><code>research</code></a> provides the guidance for this step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Stop at the research answer. Implementation, dependency installation, and policy changes are different requests.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/wait-what.html"><code>wait-what</code></a> when the last answer is hard to understand or omits context needed to follow the current proposal.</li><li>Choose <a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a> when an idea needs an agreed problem, outcome, scope, constraints, and success measures before solution work.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',17)])])}const g=a(i,[["render",n]]);export{f as __pageData,g as default};
